window.VPQ_HOSPITAL_JOURNEYS=Object.freeze({caseFiles:[{"id":"hospital-cat-urethral-obstruction-26","name":"Cosmo · blocked male cat","emoji":"🐈","species":"Cat","track":"Hospital Rounds","location":"reception","advanced":true,"intro":"A neutered male cat is vocalizing, repeatedly visiting the litter box, producing little urine, and vomiting. This is a simulated emergency; serial findings become available as the case advances.","journeyRooms":["reception","reception","exam","exam","treatment","treatment"],"steps":[{"room":"reception","q":"The owner says Cosmo is straining. Which front-desk decision is safest?","options":["Treat it as a potentially life-threatening urinary obstruction and request immediate clinical triage","Assume constipation and schedule next week","Recommend a diuretic at home"],"answer":0,"why":"A male cat unable to pass urine may rapidly develop hyperkalemia, acid-base disturbances and cardiovascular instability. Straining must not automatically be assumed to be constipation.","tag":"Urgency and triage","findings":"The owner confirms almost no urine passed overnight and reduced activity."},{"room":"reception","q":"Which focused question most changes the urgency of the history?","options":["Whether the cat prefers wet or dry food","Last confirmed urination, vomiting, previous obstruction and degree of lethargy","The coat color and litter brand alone"],"answer":1,"why":"The timing of oliguria or anuria plus systemic signs helps estimate obstruction duration and risk. History helps triage but does not replace examination.","tag":"History","findings":"Cosmo arrives weak and dehydrated; bladder is large and painful on gentle examination."},{"room":"exam","q":"What is the most useful immediate evaluation alongside a focused exam?","options":["ECG, electrolytes and renal/acid-base assessment with stabilization planning","Only a fecal flotation","A routine allergy panel"],"answer":0,"why":"Obstructed cats can develop dangerous potassium and acid–base abnormalities and azotemia. Obtain ECG and essential laboratory data without delaying lifesaving stabilization.","tag":"Diagnostics","findings":"ECG shows peaked T waves; potassium is 7.2 mmol/L (example feline reference 3.5–5.5 mmol/L)."},{"room":"exam","q":"What is the appropriate response to the elevated potassium and concerning ECG?","options":["Delay treatment until urine culture results","Urgent cardiac membrane stabilization when indicated, controlled correction of hyperkalemia and obstruction relief","Give potassium supplementation as the first intervention"],"answer":1,"why":"Hyperkalemia impairs cardiac conduction. IV calcium gluconate may protect myocardium temporarily when clinically indicated, while other treatments shift or remove potassium and relieving obstruction addresses the source. Protocols require monitoring.","tag":"Decision and physiology","findings":"After emergency stabilization, urethral catheterization restores urine outflow."},{"room":"treatment","q":"What inpatient monitoring is particularly important after unblocking?","options":["Urine output, fluid balance, renal values and serial electrolytes","Only daily body weight without urine measurement","Stop monitoring because the obstruction is resolved"],"answer":0,"why":"Postobstructive diuresis, changing potassium, perfusion and renal function can require ongoing treatment adjustments. Record urine output and reassess hydration frequently.","tag":"Treatment monitoring","findings":"Urine production increases after decompression; potassium trends downward with monitored treatment."},{"room":"treatment","q":"Which discharge plan best supports safe recovery?","options":["No follow-up because the catheter passed successfully","Analgesia, individualized urinary management, recurrence precautions and clear instructions for urgent reassessment if straining or anuria returns","Empiric antibiotics for every case regardless of evidence"],"answer":1,"why":"Preventing recurrence requires cause assessment, dietary/environmental changes when appropriate and client education. Antibiotics are not automatically indicated without evidence of infection.","tag":"Discharge and prevention","findings":"Cosmo is comfortable, urinating spontaneously and ready for individualized follow-up."}]},{"id":"hospital-dog-hemolytic-anemia-26","name":"Luna · pale and jaundiced dog","emoji":"🐕","species":"Dog","track":"Hospital Rounds","location":"reception","advanced":true,"intro":"Adult dog with acute weakness, pale gums and yellow sclera. This teaching case follows triage, anemia interpretation, diagnostics and inpatient monitoring.","journeyRooms":["reception","reception","exam","exam","treatment","treatment"],"steps":[{"room":"reception","q":"Which check-in finding requires immediate escalation?","options":["Collapse, tachycardia and very pale mucous membranes","A preference for a particular treat","Mild shedding without systemic signs"],"answer":0,"why":"Pallor and weakness can indicate inadequate oxygen delivery from severe anemia, hemorrhage or circulatory shock. Stabilization takes priority over completing a routine intake.","tag":"Triage","findings":"Luna is weak, tachycardic and icteric, without an obvious external bleed."},{"room":"reception","q":"What history helps narrow causes of anemia and jaundice?","options":["Recent medications or toxins, travel/vector exposure, bleeding, previous illness and transfusion history","Favorite sleeping spot only","Whether the owner prefers tablets or capsules"],"answer":0,"why":"Drug or toxin exposure, infections, blood loss and prior transfusions can change the differential diagnosis and guide safe testing.","tag":"Focused history","findings":"Point-of-care PCV is 18% (example canine reference 37–55%); total protein is 6.8 g/dL (example 5.5–7.5)."},{"room":"exam","q":"What is the best interpretation of severe anemia with relatively preserved total protein?","options":["Blood loss is impossible","Hemolysis becomes an important differential, but CBC, smear and additional findings are needed","The PCV proves marrow neoplasia"],"answer":1,"why":"Preserved protein may make acute external blood loss less obvious; it does not establish hemolysis. Evaluate smear, reticulocytes, bilirubin and other possible causes.","tag":"Clinical pathology","findings":"Smear shows spherocytes and persistent saline agglutination; reticulocytes are increased."},{"room":"exam","q":"Which conclusion is most defensible?","options":["Findings strongly support an immune-mediated hemolytic process while triggers and alternatives still require investigation","Spherocytes prove one specific infectious organism","Rouleaux and agglutination are identical"],"answer":0,"why":"Spherocytes and true agglutination with anemia support immune-mediated hemolysis. Infectious, neoplastic or other triggers and transfusion risks still require evaluation.","tag":"Differentials","findings":"Luna remains tachycardic, with poor exercise tolerance despite initial stabilization."},{"room":"treatment","q":"Which monitored care strategy is most appropriate?","options":["Assess perfusion and need for transfusion, pursue cause-directed therapy and monitor for thrombosis and deterioration","Give oral iron as the sole emergency intervention","Wait for spontaneous marrow recovery without reassessment"],"answer":0,"why":"Severe hemolysis can reduce oxygen delivery despite regeneration. Decisions about transfusion and immunosuppression depend on the complete patient and differential diagnosis. Thromboembolic complications merit attention.","tag":"Inpatient care","findings":"Luna receives individualized care; PCV and vital signs are followed serially."},{"room":"treatment","q":"Which combination best tracks response?","options":["PCV/HCT, reticulocyte trend, bilirubin, clinical oxygen delivery and adverse effects","A single urine color check only","One normal temperature measurement"],"answer":0,"why":"Serial laboratory and clinical reassessment distinguishes stabilization, continued RBC destruction, marrow response and complications. A single number is not enough.","tag":"Monitoring and follow-up","findings":"Luna improves clinically with a monitored plan and a specific recheck schedule."}]},{"id":"hospital-rabbit-gi-26","name":"Clover · rabbit not eating","emoji":"🐇","species":"Rabbit","track":"Hospital Rounds","location":"reception","advanced":true,"intro":"Adult pet rabbit with reduced fecal pellets, reduced appetite and hunched posture. Simulated exotics workflow; distinguish painful gastrointestinal hypomotility from obstruction.","journeyRooms":["reception","reception","exam","exam","treatment","treatment"],"steps":[{"room":"reception","q":"What is the best initial triage response?","options":["Urgent examination because anorexia and reduced fecal output in rabbits can deteriorate rapidly","Tell the owner to wait several days","Recommend unrestricted prokinetics before checking for obstruction"],"answer":0,"why":"Rabbits rely on continuous intake and gastrointestinal motility. Anorexia and reduced fecal output warrant prompt assessment for pain, dehydration, dental disease, obstruction and systemic illness.","tag":"Exotics triage","findings":"The owner reports no normal fecal pellets since the previous evening and reduced drinking."},{"room":"reception","q":"Which history is most informative?","options":["Diet and hay intake, fecal output, recent stress, dental history and access to foreign material","Whether the rabbit likes being photographed","The color of the cage door"],"answer":0,"why":"Dietary and fecal history helps identify precipitating problems. Dental pain, stress, dehydration and mechanical obstruction can all present similarly.","tag":"History","findings":"Clover is hunched and mildly hypothermic on presentation; abdomen is painful."},{"room":"exam","q":"Which next diagnostic approach best distinguishes ileus from a dangerous mechanical process?","options":["Focused examination and imaging when indicated, with hydration and glucose/electrolyte assessment","Diagnose uncomplicated stasis from reduced feces alone","Offer a new toy and skip assessment"],"answer":0,"why":"Gastrointestinal hypomotility is a syndrome, not a definitive cause. Gastric distension, obstructive patterns and metabolic instability alter feeding, medication and intervention decisions.","tag":"Diagnostic reasoning","findings":"Radiographs raise concern for substantial gastric distension and a possible obstructive pattern."},{"room":"exam","q":"What is safest given possible obstruction?","options":["Avoid force-feeding or routine prokinetics until obstruction is assessed and stabilize while obtaining exotics/surgical consultation","Give aggressive oral feeding immediately regardless of findings","Assume all rabbit anorexia is normal hairball passage"],"answer":0,"why":"Forced feeding and prokinetics may be unsafe with mechanical obstruction. Analgesia, resuscitation and urgent investigation are priorities, with definitive treatment based on the cause.","tag":"Safety decision","findings":"Further assessment excludes a mechanical obstruction; the clinician diagnoses painful functional hypomotility."},{"room":"treatment","q":"What comprehensive treatment approach now makes sense?","options":["Analgesia, corrected hydration, nutritional support as appropriate and treatment of the underlying cause, with close reassessment","An antibiotic in every case without indication","Withhold pain relief because it can mask the diagnosis"],"answer":0,"why":"Once obstruction is reasonably excluded, support for motility, hydration and intake may be appropriate. Pain control and addressing dental or systemic causes are central.","tag":"Exotics treatment","findings":"Clover begins eating hay and producing small fecal pellets."},{"room":"treatment","q":"Which recovery indicators matter most?","options":["Increasing voluntary hay consumption, fecal quantity/quality, comfort, temperature and hydration","A single pellet regardless of behavior","Weight gain from fluids alone"],"answer":0,"why":"Recovery requires sustained intake and gastrointestinal output plus comfort and clinical stability. Relapse or recurrent anorexia demands reassessment.","tag":"Recovery monitoring","findings":"Clover is brighter with sustained intake; a home-monitoring and recheck plan is discussed."}]},{"id":"hospital-dog-pyometra-26","name":"Daisy · fever and vaginal discharge","emoji":"🐕","species":"Dog","track":"Hospital Rounds","location":"reception","advanced":true,"intro":"Older intact female dog with lethargy, increased drinking, vomiting and vaginal discharge several weeks after estrus. The simulated patient requires a coordinated emergency workflow.","journeyRooms":["reception","reception","exam","exam","treatment","treatment"],"steps":[{"room":"reception","q":"Which concern should the receptionist flag urgently?","options":["Possible pyometra and systemic infection in an intact female dog","Routine seasonal shedding","Uncomplicated dietary indiscretion with no examination needed"],"answer":0,"why":"Pyometra can cause severe systemic inflammation, dehydration, endotoxemia and sepsis. Open-cervix discharge does not mean the patient is safe.","tag":"Red-flag triage","findings":"Daisy's owner confirms recent heat and worsening lethargy."},{"room":"reception","q":"Which additional history helps prioritize the assessment?","options":["Estrus timing, reproductive history, discharge, vomiting, drinking and progression of illness","Last grooming appointment alone","Favorite walking route only"],"answer":0,"why":"Post-estrus timing and clinical signs support the reproductive differential. History must be paired with a perfusion assessment and diagnostics.","tag":"Intake","findings":"Daisy has fever, tachycardia and painful abdominal palpation."},{"room":"exam","q":"What diagnostic combination best evaluates suspected pyometra and organ effects?","options":["Abdominal ultrasound together with CBC, chemistry, hydration/perfusion assessment and appropriate other testing","External discharge appearance alone","A skin scraping as the primary test"],"answer":0,"why":"Ultrasound can detect a distended fluid-filled uterus; bloodwork assesses inflammation and organ involvement. Pregnancy and other fluid-filled uterine conditions are differentials.","tag":"Diagnostic work-up","findings":"Ultrasound reveals a fluid-distended uterus; CBC suggests marked inflammatory response."},{"room":"exam","q":"Which plan most appropriately addresses the likely disease?","options":["Stabilization and urgent surgical evaluation for ovariohysterectomy when appropriate","Discharge with observation alone because the cervix is open","Routine elective spay months later without reassessment"],"answer":0,"why":"Ovariohysterectomy is definitive for most clinically ill dogs with pyometra. Correct perfusion problems and provide appropriate perioperative support; individual cases require clinical judgment.","tag":"Clinical decision","findings":"Daisy undergoes surgery after stabilization; intraoperative findings confirm purulent uterine contents."},{"room":"treatment","q":"What is most important during the immediate postoperative period?","options":["Monitor perfusion, pain, urine output, temperature and organ function; provide indicated antimicrobial and supportive care","Monitor only the incision color","Stop fluids and other monitoring regardless of recovery"],"answer":0,"why":"Sepsis-associated or perioperative complications can evolve after source control. Tailor analgesia, fluids, monitoring and antimicrobial treatment to severity and clinical findings.","tag":"Postoperative care","findings":"Daisy's perfusion and appetite improve, and follow-up chemistry is planned."},{"room":"treatment","q":"Which owner instructions best complete the patient journey?","options":["Wound care, prescribed medications, activity restriction, recheck timing and urgent signs of deterioration","No recheck is needed after surgery","Allow unrestricted activity immediately"],"answer":0,"why":"Clear discharge instructions and monitoring for poor appetite, worsening lethargy, fever, vomiting or wound complications support safe recovery.","tag":"Discharge follow-up","findings":"Daisy goes home with written instructions and a recheck appointment."}]}]});
